1	// Command grammar-refresh vendors a tree-sitter grammar into
2	// internal/sem/grammars/<lang> from its upstream git repository and records
3	// where it came from in internal/sem/grammars/grammars.json. It is a
4	// maintainer tool: it needs the network, and its output is committed, so
5	// building entire-graph never downloads anything.
6	//
7	// Usage:
8	//
9	//	go run ./cmd/grammar-refresh -lang swift -ref 0.7.4-with-generated-files
10	//	go run ./cmd/grammar-refresh -lang fsharp -ref <commit> -path fsharp
11	//	go run ./cmd/grammar-refresh -lang newlang -ref v1.0.0 -url https://github.com/o/tree-sitter-newlang
12	//
13	// The ref must contain generated sources (src/parser.c) built for ABI 13-14,
14	// the range the go-tree-sitter runtime loads. binding.go is never touched, so
15	// a new language still needs one. A grammar that changes parse results needs
16	// an IdentityRevision bump (internal/sem/provider.go) in the same commit.
17	package main
18	
19	import (
20		"flag"
21		"fmt"
22		"os"
23		"os/exec"
24		"path/filepath"
25		"regexp"
26		"strings"
27	)
28	
29	func main() {
30		var (
31			lang         = flag.String("lang", "", "grammar directory name under -dir (required)")
32			ref          = flag.String("ref", "", "tag, branch or full commit to vendor (required)")
33			url          = flag.String("url", "", "git URL; defaults to the manifest entry")
34			subdir       = flag.String("path", "", "grammar subdirectory within the repository; defaults to the manifest entry")
35			manifestPath = flag.String("manifest", "internal/sem/grammars/grammars.json", "path to the grammar manifest")
36			grammarsDir  = flag.String("dir", "internal/sem/grammars", "directory holding vendored grammars")
37		)
38		flag.Parse()
39		if *lang == "" || *ref == "" {
40			flag.Usage()
41			os.Exit(2)
42		}
43		if err := refresh(*lang, *ref, *url, *subdir, *manifestPath, *grammarsDir); err != nil {
44			fmt.Fprintln(os.Stderr, "grammar-refresh:", err)
45			os.Exit(1)
46		}
47	}
48	
49	var languageNamePattern = regexp.MustCompile(`^[a-z0-9_]+$`)
50	
51	func refresh(lang, ref, url, subdir, manifestPath, grammarsDir string) error {
52		if !languageNamePattern.MatchString(lang) {
53			return fmt.Errorf("invalid -lang %q: use the lower-case directory name under %s", lang, grammarsDir)
54		}
55		if subdir != "" && !filepath.IsLocal(subdir) {
56			return fmt.Errorf("invalid -path %q: must be a relative path inside the repository", subdir)
57		}
58		grammars, err := loadManifest(manifestPath)
59		if err != nil {
60			return err
61		}
62		var existing Grammar
63		for _, g := range grammars {
64			if g.Language == lang {
65				existing = g
66			}
67		}
68		if url == "" {
69			url = existing.URL
70		}
71		if url == "" {
72			return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
73		}
74		if subdir == "" {
75			subdir = existing.Path
76		}
77		if subdir != "" && !filepath.IsLocal(subdir) {
78			return fmt.Errorf("invalid path %q for %s in %s: must be a relative path inside the repository", subdir, lang, manifestPath)
79		}
80	
81		tmp, err := os.MkdirTemp("", "grammar-refresh-")
82		if err != nil {
83			return err
84		}
85		defer os.RemoveAll(tmp)
86		if err := git(tmp, "init", "-q"); err != nil {
